t.script:

document.addEventListener("DOMContentLoaded", function () {
  var paymentModal = document.getElementById("paymentModal");
  paymentModal.addEventListener("show.bs.modal", function (event) {
    var button = event.relatedTarget;
    var contractId = button.getAttribute("data-contract");
    document.getElementById("contractId").value = contractId;

    // load months list qua ajax
    fetch("/contract/" + contractId + "/months")
      .then(res => res.json())
      .then(data => {
        let container = document.getElementById("monthsContainer");
        container.innerHTML = "";
        if (data.months && data.months.length) {
          data.months.forEach(m => {
            let disabled = m.paid ? "disabled" : "";
            let label = m.paid ? `${m.name} ✅ Đã thanh toán` : m.name;
            container.innerHTML += `
              <div class="form-check">
                <input class="form-check-input" type="checkbox" value="${m.id}" id="month_${m.id}" ${disabled}>
                <label class="form-check-label" for="month_${m.id}">${label}</label>
              </div>
            `;
          });
        } else {
          container.innerHTML = "<p>Không có tháng nào trong hợp đồng.</p>";
        }
      })
      .catch(err => {
        console.error(err);
      });
  });

  document.getElementById("confirmPayment").addEventListener("click", function () {
    var contractId = document.getElementById("contractId").value;
    var selectedMonths = Array.from(document.querySelectorAll("#monthsContainer input:checked")).map(el => el.value);

    if (!selectedMonths.length) {
      alert("Vui lòng chọn ít nhất 1 tháng để thanh toán");
      return;
    }

    fetch("/order", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        contract_id: contractId,
        months_selected: selectedMonths
      }),
    })
    .then(res => res.json())
    .then(data => {
      if (data.error) {
        alert("Lỗi: " + data.error);
      } else if (data.payment_url) {
        window.location.href = data.payment_url;
      } else {
        alert("Không nhận được link thanh toán");
      }
    })
    .catch(err => {
      console.error(err);
      alert("Có lỗi xảy ra khi tạo thanh toán");
    });

    bootstrap.Modal.getInstance(paymentModal).hide();
  });
});
